  +						<p className={css({ fontSize: "0.875rem", opacity: 0.75, maxWidth: "48rem" })}>
  +							{tier.capReason}
  +						</p>
  +					)}
  +				</header>
  +
  +				{error && (
  +					<div
  +						role="alert"
  +						className={css({
  +							border: "1px solid var(--red)",
  +							borderRadius: "0.375rem",
  +							padding: "0.75rem 1rem",
